import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template<typename scalar_t>
__global__ void fused_group_norm_scale_kernel(
    const scalar_t* input, const scalar_t* scale, scalar_t* output,
    int batch_size, int channels, int hw, int groups,
    float eps, int channels_per_group) {

    int batch_idx = blockIdx.x / groups;
    int group_idx = blockIdx.x % groups;
    if(batch_idx >= batch_size) return;

    extern __shared__ __align__(sizeof(scalar_t)) unsigned char smem[];
    scalar_t* sum = reinterpret_cast<scalar_t*>(smem);
    scalar_t* sq_sum = sum + blockDim.x;

    int tid = threadIdx.x;
    sum[tid] = 0;
    sq_sum[tid] = 0;

    int c_start = group_idx * channels_per_group;
    int c_end = c_start + channels_per_group;
    int elements_per_group = channels_per_group * hw;

    for(int c = c_start + tid; c < c_end; c += blockDim.x) {
        for(int i = 0; i < hw; ++i) {
            scalar_t val = input[batch_idx*channels*hw + c*hw + i];
            sum[tid] += val;
            sq_sum[tid] += val * val;
        }
    }

    for(int s = blockDim.x/2; s>0; s>>=1) {
        __syncthreads();
        if(tid < s) {
            sum[tid] += sum[tid + s];
            sq_sum[tid] += sq_sum[tid + s];
        }
    }

    __syncthreads();
    scalar_t mean = sum[0] / elements_per_group;
    scalar_t var = (sq_sum[0] / elements_per_group) - (mean * mean);
    scalar_t inv_std = rsqrtf(var + eps);

    for(int c = c_start + tid; c < c_end; c += blockDim.x) {
        scalar_t s = scale[c];
        for(int i = 0; i < hw; ++i) {
            int idx = batch_idx*channels*hw + c*hw + i;
            scalar_t val = (input[idx] - mean) * inv_std * s;
            output[idx] = val;
        }
    }
}

template<typename scalar_t>
__global__ void fused_maxpool_clamp_kernel(
    const scalar_t* input, scalar_t* output,
    int batch_size, int channels,
    int input_h, int input_w,
    int kernel_size, scalar_t clamp_min, scalar_t clamp_max) {

    int out_h = blockIdx.y * blockDim.y + threadIdx.y;
    int out_w = blockIdx.z * blockDim.z + threadIdx.z;
    int c = blockIdx.x % channels;
    int b = blockIdx.x / channels;

    if(b >= batch_size || out_h >= input_h/kernel_size || out_w >= input_w/kernel_size) return;

    scalar_t max_val = -INFINITY;
    for(int i = 0; i < kernel_size; ++i) {
        for(int j = 0; j < kernel_size; ++j) {
            int h = out_h * kernel_size + i;
            int w = out_w * kernel_size + j;
            scalar_t val = input[b*channels*input_h*input_w + c*input_h*input_w + h*input_w + w];
            max_val = max(max_val, val);
        }
    }
    output[b*channels*(input_h/kernel_size)*(input_w/kernel_size) + 
           c*(input_h/kernel_size)*(input_w/kernel_size) + 
           out_h*(input_w/kernel_size) + out_w] = fminf(fmaxf(max_val, clamp_min), clamp_max);
}

torch::Tensor fused_group_norm_scale(
    torch::Tensor input, int groups, torch::Tensor scale, float eps=1e-5) {

    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int channels = sizes[1];
    int hw = sizes[2] * sizes[3];

    auto output = torch::empty_like(input);
    int channels_per_group = channels / groups;

    dim3 blocks(batch_size * groups);
    dim3 threads(256);
    size_t smem = 2 * threads.x * sizeof(float);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "fused_gn_scale", ([&] {
        fused_group_norm_scale_kernel<scalar_t><<<blocks, threads, smem>>>(
            input.data_ptr<scalar_t>(),
            scale.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch_size, channels, hw, groups,
            eps, channels_per_group);
    }));

    return output;
}

torch::Tensor fused_maxpool_clamp(
    torch::Tensor input, int kernel_size, float clamp_min, float clamp_max) {

    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int channels = sizes[1];
    int input_h = sizes[2];
    int input_w = sizes[3];

    auto output = torch::empty({batch_size, channels, 
                              input_h/kernel_size, input_w/kernel_size}, 
                              input.options());

    dim3 blocks(batch_size * channels, 
               (input_h + kernel_size-1)/kernel_size, 
               (input_w + kernel_size-1)/kernel_size);
    dim3 threads(1, 4, 4);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "fused_mp_clamp", ([&] {
        fused_maxpool_clamp_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch_size, channels,
            input_h, input_w,
            kernel_size,
            static_cast<scalar_t>(clamp_min),
            static_cast<scalar_t>(clamp_max));
    }));

    return output;
}
"""

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources='',
    cuda_sources=fused_ops_code,
    functions=['fused_group_norm_scale', 'fused_maxpool_clamp'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, padding=kernel_size//2)
        self.num_groups = num_groups
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

    def forward(self, x):
        x = self.conv(x)
        x = fused_ops.fused_group_norm_scale(x, self.num_groups, self.scale)
        x = fused_ops.fused_maxpool_clamp(x, self.maxpool_kernel_size, self.clamp_min, self.clamp_max)
        return x
